use std::collections::BTreeMap;
pub fn site() -> String { format!("{}:{}:{}", file!(), line!(), module_path!()) }
pub fn table(n: u32) -> BTreeMap<u32, String> { (0..n).map(|i| (i, format!("v{i}"))).collect() }
pub fn risky(v: &[u32], i: usize) -> u32 { v.get(i).copied().unwrap() }
